const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');const mini=document.getElementById('minimap'),mx=mini.getContext('2d');
let W,H,dpr,keys={},mouse={x:0,y:0,down:false},game=null,last=0;
const world={w:2400,h:1800};
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(game&&e.key.toLowerCase()==='r')reload();if(e.key==='Shift')keys.shift=true});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('mousedown',()=>mouse.down=true);addEventListener('mouseup',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
const start=()=>{document.getElementById('startScreen').classList.remove('visible');document.getElementById('endScreen').classList.remove('visible');document.getElementById('hud').classList.remove('hidden');newGame()};document.getElementById('playBtn').onclick=start;document.getElementById('againBtn').onclick=start;
function newGame(){game={running:true,time:0,kills:0,damage:0,ammo:24,reserve:96,reload:0,shot:0,zone:{x:1200,y:900,r:930,target:930,phase:0},p:{x:1200,y:960,hp:100,armor:55,angle:0},bots:[],bullets:[],loot:[],particles:[],cam:{x:0,y:0}};for(let i=0;i<11;i++){let a=Math.random()*6.28,r=300+Math.random()*600;game.bots.push({x:1200+Math.cos(a)*r,y:900+Math.sin(a)*r,hp:100,angle:0,shoot:Math.random(),name:['RAVEN','NOVA','KITE','GHOST','VEX','MICA'][i%6]})}for(let i=0;i<30;i++)game.loot.push({x:120+Math.random()*2160,y:100+Math.random()*1600,type:Math.random()<.5?'ammo':'med'});toast('DROP ZONE // FIND COVER');last=performance.now();requestAnimationFrame(loop)}
function reload(){if(!game||game.reload||game.ammo===24||game.reserve<=0)return;game.reload=1.5;toast('RELOADING')}
function shoot(){if(game.reload||game.ammo<=0){if(game.ammo<=0)reload();return}game.ammo--;game.shot=.13;let p=game.p;let spread=(Math.random()-.5)*.045,ang=p.angle+spread;game.bullets.push({x:p.x+Math.cos(ang)*24,y:p.y+Math.sin(ang)*24,vx:Math.cos(ang)*900,vy:Math.sin(ang)*900,life:.8,from:'p'});for(let i=0;i<4;i++)game.particles.push({x:p.x+Math.cos(ang)*26,y:p.y+Math.sin(ang)*26,vx:(Math.random()-.5)*60+Math.cos(ang)*90,vy:(Math.random()-.5)*60+Math.sin(ang)*90,life:.18,c:'#e6ff67'})}
function loop(t){if(!game||!game.running)return;let dt=Math.min((t-last)/1000,.033);last=t;update(dt);draw();requestAnimationFrame(loop)}
function update(dt){let g=game,p=g.p;g.time+=dt;if(g.reload){g.reload-=dt;if(g.reload<=0){let take=Math.min(24-g.ammo,g.reserve);g.ammo+=take;g.reserve-=take}}g.shot-=dt;let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0),len=Math.hypot(dx,dy)||1,speed=keys.shift?310:205;p.x=Math.max(30,Math.min(world.w-30,p.x+dx/len*speed*dt));p.y=Math.max(30,Math.min(world.h-30,p.y+dy/len*speed*dt));g.cam.x+=(p.x-g.cam.x)*Math.min(1,dt*8);g.cam.y+=(p.y-g.cam.y)*Math.min(1,dt*8);p.angle=Math.atan2(mouse.y-H/2,mouse.x-W/2);if(mouse.down&&g.shot<=0)shoot();
 if(g.time>8&&g.zone.r>330){g.zone.r-=dt*2.7}let z=g.zone;if(Math.hypot(p.x-z.x,p.y-z.y)>z.r){p.hp-=dt*5;p.armor=Math.max(0,p.armor-dt*1.5)}
 g.bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.from==='p'){for(let bot of g.bots){if(bot.hp>0&&Math.hypot(b.x-bot.x,b.y-bot.y)<20){bot.hp-=34;b.life=0;g.damage+=34;if(bot.hp<=0){g.kills++;g.loot.push({x:bot.x,y:bot.y,type:'ammo'});feed('YOU eliminated '+bot.name);}}}}else if(Math.hypot(b.x-p.x,b.y-p.y)<20){b.life=0;let hit=Math.min(p.armor,12);p.armor-=hit;p.hp-=12-hit*.25}});g.bullets=g.bullets.filter(b=>b.life>0&&b.x>0&&b.x<world.w&&b.y>0&&b.y<world.h);
 g.bots.forEach(b=>{if(b.hp<=0)return;let d=Math.hypot(p.x-b.x,p.y-b.y);b.angle=Math.atan2(p.y-b.y,p.x-b.x);if(d>180){b.x+=Math.cos(b.angle)*55*dt;b.y+=Math.sin(b.angle)*55*dt}b.shoot-=dt;if(d<550&&b.shoot<=0){b.shoot=1.2+Math.random();let a=b.angle;g.bullets.push({x:b.x,y:b.y,vx:Math.cos(a)*500,vy:Math.sin(a)*500,life:1,from:'bot'})}});g.bots=g.bots.filter(b=>b.hp>0);g.loot=g.loot.filter(l=>{if(Math.hypot(l.x-p.x,l.y-p.y)<28){if(l.type==='med'){p.hp=Math.min(100,p.hp+25);toast('+25 VITALS')}else{g.reserve+=30;toast('+30 AMMO')}return false}return true});g.particles.forEach(q=>{q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt});g.particles=g.particles.filter(q=>q.life>0);ui();if(p.hp<=0||g.bots.length===0)end(p.hp>0)}
function end(win){game.running=false;document.getElementById('hud').classList.add('hidden');document.getElementById('endScreen').classList.add('visible');document.getElementById('endTitle').textContent=win?'BOOYAH!':'ELIMINATED';document.getElementById('endTitle').style.color=win?'#dfff55':'#ff8065';document.getElementById('endSub').textContent=win?'You own the island.':'Your signal was lost in the storm.';document.getElementById('finalPlace').textContent=win?'#1':'#'+(game.bots.length+1);document.getElementById('finalKills').textContent=String(game.kills).padStart(2,'0');document.getElementById('finalDamage').textContent=String(game.damage).padStart(3,'0')}
function feed(t){let el=document.getElementById('killfeed');el.innerHTML='<div>✦ '+t+'</div>'+el.innerHTML;setTimeout(()=>{if(el.children.length>3)el.lastChild.remove()},3000)}function toast(t){let e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(e.x);e.x=setTimeout(()=>e.classList.remove('show'),1300)}
function ui(){let p=game.p;document.getElementById('hpText').textContent=Math.max(0,Math.ceil(p.hp));document.getElementById('hpBar').style.width=Math.max(0,p.hp)+'%';document.getElementById('armorBar').style.width=Math.max(0,p.armor/100*100)+'%';document.getElementById('ammo').textContent=game.reload?'--':game.ammo;document.getElementById('aliveCount').textContent=game.bots.length+1;document.getElementById('zoneTimer').textContent='00:'+String(Math.max(0,99-Math.floor(game.time))).padStart(2,'0')}
function draw(){let g=game,p=g.p;ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(W/2-g.cam.x,H/2-g.cam.y);drawWorld();drawZone();g.loot.forEach(l=>{ctx.fillStyle=l.type==='med'?'#ff8b67':'#e0ff58';ctx.beginPath();ctx.arc(l.x,l.y,8,0,7);ctx.fill();ctx.fillStyle='#192118';ctx.font='bold 10px Arial';ctx.textAlign='center';ctx.fillText(l.type==='med'?'+':'▦',l.x,l.y+3)});g.bots.forEach(b=>drawActor(b,false));g.bullets.forEach(b=>{ctx.fillStyle=b.from==='p'?'#edff6b':'#ff6e53';ctx.shadowBlur=10;ctx.shadowColor=ctx.fillStyle;ctx.fillRect(b.x-3,b.y-2,8,4);ctx.shadowBlur=0});g.particles.forEach(q=>{ctx.globalAlpha=q.life/.18;ctx.fillStyle=q.c;ctx.fillRect(q.x-2,q.y-2,4,4)});ctx.globalAlpha=1;drawActor(p,true);ctx.restore();drawMini();}
function drawWorld(){ctx.fillStyle='#18221b';ctx.fillRect(0,0,world.w,world.h);ctx.strokeStyle='#253529';ctx.lineWidth=2;for(let x=0;x<world.w;x+=100){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,world.h);ctx.stroke()}for(let y=0;y<world.h;y+=100){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(world.w,y);ctx.stroke()}let buildings=[[300,250,280,170],[760,400,260,220],[1540,270,360,190],[1840,840,260,310],[350,1230,330,210],[1120,1280,380,220],[1650,1350,300,200],[850,850,180,120]];buildings.forEach((b,i)=>{ctx.fillStyle=i%2?'#29382b':'#304331';ctx.fillRect(...b);ctx.strokeStyle='#526553';ctx.strokeRect(...b);ctx.fillStyle='#8fa06c55';for(let x=b[0]+25;x<b[0]+b[2]-10;x+=45)ctx.fillRect(x,b[1]+18,20,7)});ctx.fillStyle='#49634b';for(let i=0;i<35;i++){let x=(i*347)%2300+40,y=(i*197)%1700+40;ctx.beginPath();ctx.arc(x,y,14+(i%3)*5,0,7);ctx.fill();ctx.fillStyle='#607c50';ctx.beginPath();ctx.arc(x-4,y-8,8,0,7);ctx.fill();ctx.fillStyle='#49634b'}ctx.strokeStyle='#5b7655';ctx.lineWidth=13;ctx.beginPath();ctx.moveTo(0,610);ctx.bezierCurveTo(500,530,600,760,1100,650);ctx.bezierCurveTo(1600,540,1900,720,2400,600);ctx.stroke();ctx.lineWidth=2}
function drawZone(){let z=game.zone;ctx.fillStyle='rgba(102,39,61,.28)';ctx.beginPath();ctx.rect(0,0,world.w,world.h);ctx.arc(z.x,z.y,z.r,0,7,true);ctx.fill('evenodd');ctx.strokeStyle='#dfff55';ctx.lineWidth=4;ctx.setLineDash([12,10]);ctx.beginPath();ctx.arc(z.x,z.y,z.r,0,7);ctx.stroke();ctx.setLineDash([])}
function drawActor(a,player){ctx.save();ctx.translate(a.x,a.y);ctx.rotate(a.angle);ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(0,11,20,9,0,0,7);ctx.fill();ctx.fillStyle=player?'#e1ff5b':'#e66c58';ctx.beginPath();ctx.arc(0,0,14,0,7);ctx.fill();ctx.fillStyle='#d9e3d3';ctx.fillRect(7,-4,19,8);ctx.fillStyle=player?'#334d2d':'#4a2928';ctx.fillRect(-10,-10,10,20);ctx.restore();if(!player&&a.hp<100){ctx.fillStyle='#182218';ctx.fillRect(a.x-18,a.y-27,36,3);ctx.fillStyle='#e66c58';ctx.fillRect(a.x-18,a.y-27,36*a.hp/100,3)}}
function drawMini(){let s=170;mx.clearRect(0,0,s,s);mx.fillStyle='#17251a';mx.fillRect(0,0,s,s);let sc=s/world.w;mx.strokeStyle='#668050';mx.lineWidth=1;for(let x=0;x<world.w;x+=300){mx.beginPath();mx.moveTo(x*sc,0);mx.lineTo(x*sc,s);mx.stroke()}mx.strokeStyle='#dfff55';mx.beginPath();mx.arc(game.zone.x*sc,game.zone.y*sc,game.zone.r*sc,0,7);mx.stroke();game.loot.forEach(l=>{mx.fillStyle='#b8d84e';mx.fillRect(l.x*sc-1,l.y*sc-1,2,2)});game.bots.forEach(b=>{mx.fillStyle='#ee725d';mx.fillRect(b.x*sc-2,b.y*sc-2,4,4)});mx.fillStyle='#fff';mx.beginPath();mx.arc(game.p.x*sc,game.p.y*sc,3,0,7);mx.fill()}

